CREATE FUNCTION pg_temp.review_fixture(mode text DEFAULT 'calendar_days',basis text DEFAULT 'monthly',join_on date DEFAULT '2030-01-25',transition boolean DEFAULT false) RETURNS jsonb LANGUAGE sql AS $$
 SELECT jsonb_build_object('engine','cube4-review-v3-source-safe','period',jsonb_build_object('id','c4498000-0000-4000-8000-000000000001','starts_on','2030-01-25','ends_on','2030-02-24','is_transition',transition),
 'employees',jsonb_build_array(jsonb_build_object('name','Fixture Employee','code','CALCQA','employment',jsonb_build_object('id','c4495000-0000-4000-8000-000000000001','employee_id','c4494000-0000-4000-8000-000000000001','pay_basis',basis,'start_date',join_on,'end_date',NULL))),
 'compensation',jsonb_build_array(jsonb_build_object('id','c4496000-0000-4000-8000-000000000001','employment_id','c4495000-0000-4000-8000-000000000001','valid_from','2030-01-01','valid_until',NULL,'amount',CASE WHEN basis='daily' THEN 100 ELSE 3000 END)),
 'assignments',jsonb_build_array(jsonb_build_object('employment_id','c4495000-0000-4000-8000-000000000001','valid_from','2030-01-01','valid_until',NULL)),
 'inputs',jsonb_build_array(jsonb_build_object('head',jsonb_build_object('id','c4497000-0000-4000-8000-000000000001','kind','policy'),'version',jsonb_build_object('revision',1,'effective_from','2030-01-01','effective_until',NULL,'status','draft','data',jsonb_build_object('mode',mode)))) || CASE WHEN basis='daily' THEN jsonb_build_array(jsonb_build_object('head',jsonb_build_object('id','c4497000-0000-4000-8000-000000000005','kind','manual_units','employment_id','c4495000-0000-4000-8000-000000000001','period_id','c4498000-0000-4000-8000-000000000001'),'version',jsonb_build_object('revision',1,'effective_from','2030-01-25','effective_until','2030-02-25','status','approved','data','{"units":"5"}'::jsonb))) ELSE '[]'::jsonb END,
 'packs','[]'::jsonb,'optional','{"time":false,"leave":false,"finance":"adjustments_only"}'::jsonb,'corrections','[]'::jsonb)
$$;
CREATE FUNCTION pg_temp.with_component(manifest jsonb,value numeric DEFAULT 300,method text DEFAULT 'fixed',proration text DEFAULT NULL) RETURNS jsonb LANGUAGE sql AS $$
 SELECT manifest||jsonb_build_object('inputs',manifest->'inputs'||jsonb_build_array(
 jsonb_build_object('head',jsonb_build_object('id','c4497000-0000-4000-8000-000000000002','kind','component'),'version',jsonb_build_object('id','c4497100-0000-4000-8000-000000000002','revision',1,'effective_from','2030-01-01','effective_until',NULL,'status','draft','data',jsonb_strip_nulls(jsonb_build_object('active','true','name','Fixture component','classification','earning','calculation',method,'base',CASE WHEN method='percentage' THEN 'base_pay' ELSE '' END,'behavior','recurring','proration',proration)))),
 jsonb_build_object('head',jsonb_build_object('id','c4497000-0000-4000-8000-000000000003','kind','recurring','employment_id','c4495000-0000-4000-8000-000000000001'),'version',jsonb_build_object('revision',1,'effective_from','2030-01-01','effective_until',NULL,'status','draft','data',jsonb_build_object('component_id','c4497000-0000-4000-8000-000000000002','value',value)))))
$$;
