-- Pure dated recurring fixtures, preserving original component while changing method at next period boundary.
CREATE FUNCTION pg_temp.changed_component(old_method text,new_method text,renew boolean DEFAULT false) RETURNS jsonb LANGUAGE sql AS $$
 SELECT pg_temp.with_component(pg_temp.review_fixture(),CASE WHEN old_method='fixed' THEN 300 ELSE 10 END,old_method)||jsonb_build_object('inputs',pg_temp.with_component(pg_temp.review_fixture(),CASE WHEN old_method='fixed' THEN 300 ELSE 10 END,old_method)->'inputs'||jsonb_build_array(
 jsonb_build_object('head',jsonb_build_object('id','c4497000-0000-4000-8000-000000000002','kind','component'),'version',jsonb_build_object('id','c4497100-0000-4000-8000-000000000004','revision',2,'effective_from','2030-01-25','effective_until',NULL,'status','draft','data',jsonb_build_object('active','true','name','Changed method','classification','earning','calculation',new_method,'base',CASE WHEN new_method='percentage' THEN 'base_pay' ELSE '' END,'behavior','recurring'))))||CASE WHEN renew THEN jsonb_build_array(jsonb_build_object('head',jsonb_build_object('id','c4497000-0000-4000-8000-000000000003','kind','recurring','employment_id','c4495000-0000-4000-8000-000000000001'),'version',jsonb_build_object('revision',2,'effective_from','2030-01-25','effective_until',NULL,'status','draft','data',jsonb_build_object('component_id','c4497000-0000-4000-8000-000000000002','value',CASE WHEN new_method='percentage' THEN 10 ELSE 300 END)))) ELSE '[]'::jsonb END)
$$;
SELECT ok(EXISTS(SELECT 1 FROM jsonb_array_elements(payroll.build_review(pg_temp.changed_component('fixed','percentage'))->'issues')i WHERE i->>'code'='recurring_interpretation_changed'),'old fixed300 assignment cannot silently become300percent');
SELECT is(payroll.build_review(pg_temp.changed_component('fixed','percentage'))->'gross','null'::jsonb,'blocked recurring candidate has no authoritative gross');
SELECT is(payroll.build_review(pg_temp.changed_component('fixed','percentage'))->>'gross_complete','false','unrenewed fixed-to-percentage remains incomplete');
SELECT is((payroll.build_review(pg_temp.changed_component('fixed','percentage'))->>'known_gross')::numeric,3000::numeric,'blocked recurring candidate preserves known base only without invented9000 earning');
SELECT is(payroll.build_review(pg_temp.changed_component('percentage','fixed'))->'gross','null'::jsonb,'inverse unrenewed candidate also has no authoritative gross');
SELECT is((payroll.build_review(pg_temp.changed_component('percentage','fixed'))->>'known_gross')::numeric,3000::numeric,'inverse blocked candidate preserves known base only');
SELECT is((payroll.build_review(pg_temp.changed_component('fixed','percentage',true))->'employees'->0->>'gross')::numeric,3300::numeric,'renewed assignment explicitly authorizes earned-base10percent');
SELECT ok(EXISTS(SELECT 1 FROM jsonb_array_elements(payroll.build_review(pg_temp.changed_component('percentage','fixed'))->'issues')i WHERE i->>'code'='recurring_interpretation_changed'),'inverse percentage-to-fixed also requires renewed monetary interpretation');
SELECT is((payroll.build_review(pg_temp.changed_component('percentage','fixed',true))->'employees'->0->>'gross')::numeric,3300::numeric,'renewed inverse explicitly authorizes fixed300');
SELECT is((payroll.build_review(jsonb_set(jsonb_set(pg_temp.changed_component('fixed','percentage'),'{period,starts_on}','"2030-01-01"'),'{period,ends_on}','"2030-01-24"')||jsonb_build_object('employees',pg_temp.review_fixture(join_on=>'2030-01-01')->'employees'))->'employees'->0->>'gross')::numeric,3300::numeric,'future component method does not resurrect or reinterpret older period assignment');

-- Latest dated policy expires exclusively; no previous active policy is resurrected.
CREATE FUNCTION pg_temp.expiring_policy(until_on date) RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_set(pg_temp.review_fixture(),'{inputs,0,version,effective_until}',to_jsonb(until_on::text)) $$;
SELECT ok(EXISTS(SELECT 1 FROM jsonb_array_elements(payroll.build_review(pg_temp.expiring_policy('2030-01-25'))->'issues')i WHERE i->>'code'='policy_coverage_gap'),'policy expired at start blocks coverage');
SELECT ok(EXISTS(SELECT 1 FROM jsonb_array_elements(payroll.build_review(pg_temp.expiring_policy('2030-02-10'))->'issues')i WHERE i->>'code'='policy_coverage_gap'),'policy expiry inside period blocks coverage');
SELECT ok(EXISTS(SELECT 1 FROM jsonb_array_elements(payroll.build_review(pg_temp.expiring_policy('2030-02-24'))->'issues')i WHERE i->>'code'='policy_coverage_gap'),'exclusive expiry at last local date blocks final day');
SELECT is((payroll.build_review(pg_temp.expiring_policy('2030-02-25'))->'employees'->0->>'base')::numeric,3000::numeric,'expiry after inclusive period end retains complete coverage');
SELECT ok(EXISTS(SELECT 1 FROM jsonb_array_elements(payroll.build_review(pg_temp.review_fixture()||jsonb_build_object('inputs',pg_temp.review_fixture()->'inputs'||jsonb_build_array(jsonb_set(jsonb_set(jsonb_set(pg_temp.review_fixture()->'inputs'->0,'{version,revision}','2'),'{version,effective_from}','"2030-01-10"'),'{version,effective_until}','"2030-01-25"'))))->'issues')i WHERE i->>'code'='policy_coverage_gap'),'expired newer version suppresses older unexpired policy');
SELECT ok(EXISTS(SELECT 1 FROM jsonb_array_elements(payroll.build_review(jsonb_set(pg_temp.review_fixture(),'{inputs,0,version,status}','"cancelled"'))->'issues')i WHERE i->>'code'='policy_coverage_gap'),'cancelled latest policy cannot cover period');

