CREATE FUNCTION pg_temp.reject_review_final_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='run_finalized' THEN RAISE EXCEPTION 'review_final_audit_failure' USING ERRCODE='P0001';END IF;RETURN NEW;END $$;
CREATE TRIGGER review_final_audit_failure BEFORE INSERT ON payroll.audit_events FOR EACH ROW EXECUTE FUNCTION pg_temp.reject_review_final_audit();
SELECT throws_ok($$SELECT payroll.append_final_output('c4491000-0000-4000-8000-000000000001','c4499200-0000-4000-8000-000000000001','c4499200-0000-4000-8000-000000000002','c4490000-0000-4000-8000-000000000001',2,'c4499300-0000-4000-8000-000000000001')$$,'P0001','review_final_audit_failure','mandatory final audit failure rolls back adjustment consumption');
SELECT is((SELECT count(*)::integer FROM payroll.input_versions WHERE tenant_id='c4491000-0000-4000-8000-000000000001' AND status='applied'),0,'failed finalization creates no applied adjustment version');
SELECT is((SELECT count(*)::integer FROM payroll.final_contexts WHERE tenant_id='c4491000-0000-4000-8000-000000000001'),0,'failed consumption audit creates no final payable');
DROP TRIGGER review_final_audit_failure ON payroll.audit_events;
