SELECT is((SELECT v.status FROM payroll.input_heads h JOIN payroll.input_versions v ON v.tenant_id=h.tenant_id AND v.head_id=h.id AND v.revision=h.revision WHERE h.tenant_id='c4491000-0000-4000-8000-000000000001' AND h.id=current_setting('test.excluded_adj')::uuid),'approved','excluded Employee adjustment remains approved unconsumed');
SELECT is(payroll.append_final_output('c4491000-0000-4000-8000-000000000001','c4499200-0000-4000-8000-000000000001','c4499200-0000-4000-8000-000000000002','c4490000-0000-4000-8000-000000000001',2,'c4499300-0000-4000-8000-000000000001'),current_setting('test.final')::uuid,'original append receipt replay has no second adjustment consumption');
