-- Payment evidence bounds reject PostgreSQL-only dates before any financial mutation.
CREATE FUNCTION pg_temp.payment_date(day date) RETURNS jsonb LANGUAGE sql AS $$ SELECT public.payroll_record_payment('c4491000-0000-4000-8000-000000000001','c4493000-0000-4000-8000-000000000001',current_setting('test.final')::uuid,0,'allocations',day,'Review historical evidence','NONLEGAL external date regression','[{"employment_id":"c4495000-0000-4000-8000-000000000001","amount":"1.00"}]',NULL,true,'c4499400-0000-4000-8000-000000000001') $$;
GRANT EXECUTE ON FUNCTION pg_temp.payment_date(date) TO authenticated;
SELECT set_config('test.date_before',jsonb_build_object('events',(SELECT count(*) FROM payroll.payment_events WHERE tenant_id='c4491000-0000-4000-8000-000000000001'),'allocations',(SELECT count(*) FROM payroll.payment_allocations WHERE tenant_id='c4491000-0000-4000-8000-000000000001'),'revision',(SELECT revision FROM payroll.payment_heads WHERE tenant_id='c4491000-0000-4000-8000-000000000001' AND output_id=current_setting('test.final')::uuid),'audit',(SELECT count(*) FROM payroll.audit_events WHERE tenant_id='c4491000-0000-4000-8000-000000000001'),'receipts',(SELECT count(*) FROM payroll.command_receipts WHERE tenant_id='c4491000-0000-4000-8000-000000000001'))::text,true);
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT pg_temp.payment_date('-infinity')$$,'22023','payroll_payment_invalid','negative infinity is not civil payment evidence');
SELECT throws_ok($$SELECT pg_temp.payment_date('infinity')$$,'22023','payroll_payment_invalid','positive infinity is not civil payment evidence');
SELECT throws_ok($$SELECT pg_temp.payment_date('0001-01-01 BC')$$,'22023','payroll_payment_invalid','BC evidence is not ISO civil year0001');
SELECT throws_ok($$SELECT pg_temp.payment_date('10000-01-01')$$,'22023','payroll_payment_invalid','six digit year is not renderable ISO evidence');
SELECT throws_ok($$SELECT pg_temp.payment_date('2031-01-01')$$,'22023','payroll_payment_invalid','ordinary finite future evidence remains refused');
RESET ROLE;
SELECT is(jsonb_build_object('events',(SELECT count(*) FROM payroll.payment_events WHERE tenant_id='c4491000-0000-4000-8000-000000000001'),'allocations',(SELECT count(*) FROM payroll.payment_allocations WHERE tenant_id='c4491000-0000-4000-8000-000000000001'),'revision',(SELECT revision FROM payroll.payment_heads WHERE tenant_id='c4491000-0000-4000-8000-000000000001' AND output_id=current_setting('test.final')::uuid),'audit',(SELECT count(*) FROM payroll.audit_events WHERE tenant_id='c4491000-0000-4000-8000-000000000001'),'receipts',(SELECT count(*) FROM payroll.command_receipts WHERE tenant_id='c4491000-0000-4000-8000-000000000001')),current_setting('test.date_before')::jsonb,'invalid dates leave all payment financial and audit receipt state unchanged');
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT pg_temp.payment_date('0001-01-01')$$,'valid earliest ISO historical date is retained without clamp');
RESET ROLE;
